CREATE TABLE module_state (module TEXT NOT NULL,key TEXT NOT NULL,document TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(module,key));
CREATE TABLE automod_evidence (id TEXT PRIMARY KEY,rule_id TEXT NOT NULL,user_id TEXT NOT NULL,channel_id TEXT NOT NULL,message_id TEXT,excerpt TEXT NOT NULL,explanation TEXT NOT NULL,action TEXT NOT NULL,case_id INTEGER,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,reviewed_by TEXT);
CREATE TABLE role_panels (id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,message_id TEXT,version INTEGER NOT NULL,document TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE form_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT,form_id TEXT NOT NULL,user_id TEXT NOT NULL,form_version INTEGER NOT NULL,definition TEXT NOT NULL,answers TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',assignee TEXT,decision TEXT,case_id INTEGER,message_id TEXT,thread_id TEXT,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,delivery_state TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX form_expiry ON form_submissions(expires_at);
CREATE TABLE giveaways (id TEXT PRIMARY KEY,document TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,message_id TEXT,actor TEXT NOT NULL,created_at INTEGER NOT NULL,results TEXT NOT NULL DEFAULT '[]',delivery_state TEXT NOT NULL DEFAULT 'pending',reason TEXT);
CREATE TABLE giveaway_entries (giveaway_id TEXT NOT NULL REFERENCES giveaways(id) ON DELETE CASCADE,user_id TEXT NOT NULL,chances INTEGER NOT NULL DEFAULT 1,referrer TEXT,last_bonus TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(giveaway_id,user_id));
CREATE TABLE giveaway_history (id INTEGER PRIMARY KEY AUTOINCREMENT,giveaway_id TEXT NOT NULL,actor TEXT NOT NULL,result TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE starboard_messages (board_id TEXT NOT NULL,source_id TEXT NOT NULL,source_channel TEXT NOT NULL,message_id TEXT,votes INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(board_id,source_id));
CREATE TABLE feed_sources (provider TEXT NOT NULL,source TEXT NOT NULL,cursor TEXT,next_at INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,error TEXT,state TEXT NOT NULL DEFAULT 'new',PRIMARY KEY(provider,source));
CREATE TABLE feed_items (provider TEXT NOT NULL,source TEXT NOT NULL,content_id TEXT NOT NULL,document TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(provider,source,content_id));
CREATE TABLE feed_delivery (feed_id TEXT NOT NULL,content_id TEXT NOT NULL,document TEXT NOT NULL,channel_id TEXT NOT NULL,message_id TEXT,state TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,error TEXT,PRIMARY KEY(feed_id,content_id));
CREATE TABLE guild_backups (id TEXT PRIMARY KEY,created_at INTEGER NOT NULL,state TEXT NOT NULL,filename TEXT,error TEXT,summary TEXT);
CREATE TABLE guild_restores (id TEXT PRIMARY KEY,backup_id TEXT NOT NULL,actor TEXT NOT NULL,plan TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,mapping TEXT NOT NULL DEFAULT '{}',error TEXT);
CREATE TABLE guild_restore_steps (restore_id TEXT NOT NULL,source_id TEXT NOT NULL,kind TEXT NOT NULL,new_id TEXT,state TEXT NOT NULL,error TEXT,PRIMARY KEY(restore_id,kind,source_id));
